{"title": "CSCI-472: Historical & Current Perspectives in Computer Science", "learningObjectives": [
        "Define the core ethical principles guiding computing professionals and their societal impact.",
        "Explain how responsible technical communication ensures research integrity and accurate reporting.",
        "Analyze how historical milestones and past issues shape modern computer science design and decision-making."
      ], "beats": [
        {
          "title": "Course Foundations & Scope",
          "claim": "CSCI-472 provides students with a historical and current perspective on computer science, focusing on early history, key figures, major milestones, and contemporary issues like law",
          "example": "Students will review the course catalog description to identify the required background in CS theories, algorithms, and data structures.",
          "visualDirection": "Display the official course catalog description on screen with highlighted sections for prerequisites and topics.",
          "sourceIds": ["rit-csci-472"]
        },
        {
          "title": "Prerequisites & Course Restrictions",
          "claim": "The course is restricted to students with at least fourth-year standing and cannot be taken if credit for CSCI-471 has already been received.",
          "example": "Instructor will verify student standing and prior course registration before allowing enrollment.",
          "visualDirection": "Show a checklist graphic listing 'Fourth-year standing' and 'No CSCI-471 credit' as mandatory enrollment criteria.",
          "sourceIds": ["rit-csci-472"]
        },
        {
          "title": "Early History of Computer Science",
          "claim": "The early history of computer science establishes the foundational concepts and historical context for modern computing practices.",
          "example": "Students will examine early computing devices and their evolution to understand how historical milestones shape modern designs.",
          "visualDirection": "Present a timeline graphic showing key early computing devices and their chronological progression.",
          "sourceIds": ["rit-csci-472"]
        },
        {

          "title": "People Who Shaped Computer Science",
          "claim": "A study of the people who shaped computer science highlights the contributions of individuals who advanced the field.",
          "example": "Students will profile key historical figures and analyze their specific roles in advancing computer science.",
          "visualDirection": "Display a collage of portraits of influential computer scientists with brief biographical notes.",
          "sourceIds": ["rit-csci-472"]
        },
        {
          "title": "Major Milestones in Computer Science",
          "claim": "A discussion of major milestones in computer science traces the significant developments that transformed the field.",
          "example": "Students will map major technological breakthroughs to understand how past issues affect modern designs and decision making by computer scientists.",
          "visualDirection": "Show a flowchart connecting major milestones to their impact on contemporary computing practices.",
          "sourceIds": ["rit-csci-472"]
        },
        {
          "title": "Current Issues: Legal & Ethical Frameworks",
          "claim": "Students will study current issues in computer science, including legal and ethical considerations that guide professional practice.",
          "example": "Students will review the ACM Code of Ethics to identify how computing professionals should avoid harm and be honest and trustworthy.",
          "visualDirection": "Display the ACM Code of Ethics principles as a set of icons with corresponding text summaries.",
          "sourceIds": ["acm-code-of-ethics"]
        },
        {
          "title": "Current Issues: Diversity, Equity, Inclusion, & Accessibility",
          "claim": "The course covers diversity, equity, inclusion, and accessibility issues, emphasizing how past issues affect modern designs and decision making by computer scientists.",
          "example": "Students will analyze case studies showing how historical biases influenced modern accessibility standards in software development.",
          "visualDirection": "Present a Venn diagram overlapping 'Past Issues' and 'Modern Designs' with 'Diversity, Equity, Inclusion, and Accessibility' in the intersection.",
          "sourceIds": ["rit-csci-472"]
        },
        {
          "title": "Current Issues: Privacy & Security",
          "claim": "Students will examine privacy and security issues, learning how professionals should respect privacy and maintain robust security when appropriate.",
          "example": "Students will evaluate a scenario where a software update must balance user privacy with system security requirements.",
          "visualDirection": "Show a lock-and-shield icon representing privacy and security, with a checklist of ethical computing decision steps.",
          "sourceIds": ["acm-code-of-ethics"]
        },
        {
          "title": "Responsible Technical Communication",
          "claim": "Responsible technical communication distinguishes claims from evidence, cites prior work, and ensures methods are described well enough for readers to evaluate the work.",
          "example": "Students will draft a research abstract that clearly separates claims from evidence and cites prior work.",
          "visualDirection": "Display a side-by-side comparison of a 'misleading conclusion' vs. an 'accurate result' report with annotations.",
          "sourceIds": ["acm-research-practice"]
        },
        {
          "title": "Research Integrity & Problem-Solving Methods",
          "claim": "Authors should preserve research integrity and avoid plagiarism, fabrication, and falsification, while maintaining high standards of professional competence.",
          "example": "Students will practice identifying potential conflicts of interest and disclose them according to publication policy.",
          "visualDirection": "Show a checklist graphic listing 'Avoid plagiarism', 'Disclose conflicts', and 'Maintain high standards' as research integrity steps.",
          "sourceIds": ["acm-research-practice"]
        }
      ]}
